import { FaMusic } from "react-icons/fa6";
import { GoChevronUp, GoListUnordered, GoLinkExternal } from "react-icons/go";
import { BiCommentDetail } from "react-icons/bi";
import { useColorPalette } from "../../../hooks/useColorPalette";
